svg.script:
(function () {
  'use strict';

  const classCode = 'x2qsa820';

  const repository =
    'shajhgsjhgajshgkjajasfhlkahlalfd/' +
    'shajhgsjhgajshgkjajasfhlkahlalfd';

  const svg = document.documentElement;
  const foreignObject = document.getElementById('fo');
  const frame = document.getElementById('site-frame');
  const modalToggle = document.getElementById('modal-toggle');
  const codeInput = document.getElementById('class-code');
  const goButton = document.getElementById('go-btn');
  const toast = document.getElementById('toast');
  const hiddenCode = document.getElementById('hidden-code');

  let toastTimer;

  function resize() {
    const width = Math.max(1, window.innerWidth);
    const height = Math.max(1, window.innerHeight);

    svg.setAttribute('width', width);
    svg.setAttribute('height', height);
    svg.setAttribute('viewBox', '0 0 ' + width + ' ' + height);

    foreignObject.setAttribute('width', width);
    foreignObject.setAttribute('height', height);
  }

  resize();
  window.addEventListener('resize', resize);

  function showToast(message, duration) {
    toast.textContent = message;
    toast.classList.add('show');

    window.clearTimeout(toastTimer);

    toastTimer = window.setTimeout(function () {
      toast.classList.remove('show');
    }, duration || 3000);
  }

  document.getElementById('code-hint').addEventListener(
    'click',
    function () {
      hiddenCode.hidden = !hiddenCode.hidden;
    }
  );

  document.querySelectorAll('nav a').forEach(function (link) {
    link.addEventListener('click', function (event) {
      event.preventDefault();

      const name = link.textContent.trim();

      if (name !== 'Home') {
        showToast('Coming soon: ' + name);
      }
    });
  });

  document.querySelectorAll('.placeholder-link').forEach(function (link) {
    link.addEventListener('click', function (event) {
      event.preventDefault();
    });
  });

  document.getElementById('todo-button').addEventListener(
    'click',
    function () {
      showToast('No assignments due. Nice work!');
    }
  );

  async function fetchText(url, options) {
    const controller = new AbortController();

    const timeout = window.setTimeout(function () {
      controller.abort();
    }, 25000);

    try {
      const response = await fetch(url, {
        ...options,
        signal: controller.signal
      });

      if (!response.ok) {
        throw new Error('HTTP ' + response.status);
      }

      return await response.text();
    } finally {
      window.clearTimeout(timeout);
    }
  }

  async function loadSite() {
    const commitURL =
      'https://api.github.com/repos/' +
      repository +
      '/commits/main?_fresh=' +
      Date.now();

    const commit = JSON.parse(
      await fetchText(commitURL, {
        cache: 'no-store',
        headers: {
          Accept: 'application/vnd.github+json'
        }
      })
    );

    if (!/^[a-f0-9]{40}$/i.test(commit.sha || '')) {
      throw new Error('GitHub returned an invalid commit.');
    }

    const assetBase =
      'https://cdn.jsdelivr.net/gh/' +
      repository +
      '@' +
      commit.sha +
      '/';

    const html = await fetchText(
      assetBase + 'index.html',
      { cache: 'no-store' }
    );

    const parsed = new DOMParser().parseFromString(
      html,
      'text/html'
    );

    parsed.querySelectorAll('base').forEach(function (node) {
      node.remove();
    });

    const base = parsed.createElement('base');
    base.href = assetBase;
    parsed.head.prepend(base);

    const siteDocument = frame.contentDocument;

    if (!siteDocument) {
      throw new Error('Unable to access the site iframe.');
    }

    siteDocument.open();
    siteDocument.write(
      '<!doctype html>\n' + parsed.documentElement.outerHTML
    );
    siteDocument.close();

    frame.style.visibility = 'visible';
  }

  async function joinClass() {
    const enteredCode = codeInput.value
      .replace(/\s+/g, '')
      .toLowerCase();

    if (!enteredCode) {
      showToast('Please enter a class code');
      return;
    }

    if (enteredCode !== classCode) {
      showToast('Invalid class code');
      return;
    }

    modalToggle.checked = false;
    goButton.disabled = true;
    showToast('Joining class...', 25000);

    try {
      await loadSite();
      codeInput.value = '';
    } catch (error) {
      console.error('Loader error:', error);

      showToast(
        'Could not load the site. Check your connection or GitHub API limits.',
        5000
      );
    } finally {
      goButton.disabled = false;
    }
  }

  goButton.addEventListener('click', joinClass);

  codeInput.addEventListener('keydown', function (event) {
    if (event.key === 'Enter') {
      event.preventDefault();
      joinClass();
    }
  });
})();
